  let draftFlag=null,flagReturn='startModal',zoom=1,toastTimer;

  function flagConfigFor(nation){return state.player===nation.id&&state.flag?state.flag:nation}
  function flagMarkup(config,extra=''){const p=config.pattern||'horizontal',a=config.c1||'#1c3547',b=config.c2||'#f5f0df',c=config.c3||'#d5aa57';let bg;
    if(p==='vertical')bg=`linear-gradient(90deg,${a} 0 33.33%,${b} 33.33% 66.66%,${c} 66.66%)`;
    else if(p==='diagonal')bg=`linear-gradient(135deg,${a} 0 37%,${b} 37% 67%,${c} 67%)`;
    else if(p==='cross')bg=`linear-gradient(90deg,transparent 0 40%,${c} 40% 60%,transparent 60%),linear-gradient(0deg,${a} 0 40%,${b} 40% 60%,${a} 60%)`;
    else if(p==='quartered')bg=`linear-gradient(90deg,${a} 0 50%,${b} 50%),linear-gradient(0deg,transparent 0 50%,${c} 50%)`;
    else if(p==='solid')bg=a;
    else bg=`linear-gradient(0deg,${c} 0 24%,${b} 24% 76%,${a} 76%)`;
    const sym=config.symbol||'★';return `<span class="flag ${extra}" style="background:${bg}">${sym!=='—'?`<span class="flag-symbol" style="color:${p==='solid'?b:'#fff'}">${sym}</span>`:''}</span>`;
  }
  function paintFlag(el,config){el.innerHTML=flagMarkup(config);}
  function territoryPath(t){let x=t.x,y=t.y,w=t.w,h=t.h;let tweaks=[[0,0],[4,-2],[-2,1],[0,0]][t.col];return `M${x+4} ${y+2} L${x+w*.48} ${y} L${x+w-3} ${y+4} L${x+w} ${y+h*.49} L${x+w-4} ${y+h-2} L${x+w*.53} ${y+h} L${x+2} ${y+h-3} L${x} ${y+h*.52} Z`;}
  function initMap(){const g=$('territories');g.innerHTML='';territories.forEach(t=>{const group=document.createElementNS('http://www.w3.org/2000/svg','g');group.dataset.id=t.id;group.classList.add('territory-group');group.setAttribute('tabindex','0');group.setAttribute('role','button');group.setAttribute('aria-label',`${t.name}, ${t.type}`);const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',territoryPath(t));path.classList.add('territory');path.dataset.id=t.id;const label=document.createElementNS('http://www.w3.org/2000/svg','text');label.setAttribute('x',t.x+t.w/2);label.setAttribute('y',t.y+t.h/2-2);label.classList.add('territory-name');label.textContent=t.name;const sub=document.createElementNS('http://www.w3.org/2000/svg','text');sub.setAttribute('x',t.x+t.w/2);sub.setAttribute('y',t.y+t.h/2+13);sub.classList.add('territory-sub');sub.textContent=t.type;const troops=document.createElementNS('http://www.w3.org/2000/svg','text');troops.setAttribute('x',t.x+t.w-18);troops.setAttribute('y',t.y+20);troops.classList.add('territory-army');group.append(path,label,sub,troops);group.addEventListener('click',()=>selectTerritory(t.id));group.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectTerritory(t.id)}});g.appendChild(group)});}
  function faction(id){return nations.find(n=>n.id===id)||{id:'neutral',name:'Neutros',color:'#8c9ca8',dark:'#71818c',motto:''}}
  function territory(id){return territories.find(t=>t.id===id)}
  function owned(){return territories.filter(t=>t.owner===state.player)}
  function countArmy(){return owned().reduce((sum,t)=>sum+t.troops,0)}
  function income(){const count=owned().length;return {industry:Math.max(1,Math.floor(count/2)),manpower:Math.max(1,Math.ceil(count/3)),influence:Math.max(1,Math.floor(count/4))}}
  function render(){if(!state.started)return;const n=faction(state.player);paintFlag($('playerFlag'),flagConfigFor(state.player));$('playerName').textContent=n.name;$('playerMotto').textContent=n.motto;$('industryValue').textContent=state.industry;$('manpowerValue').textContent=state.manpower;$('influenceValue').textContent=state.influence;const inc=income();$('industryIncome').textContent=`+${inc.industry}`;$('manpowerIncome').textContent=`+${inc.manpower}`;$('influenceIncome').textContent=`+${inc.influence}`;$('territoryCount').textContent=owned().length;$('armyCount').textContent=countArmy();$('turnCount').textContent=state.turn;$('turnBadge').textContent=`TURNO ${state.turn}`;$('ownedMapCount').textContent=owned().length;$('objectiveCount').textContent=`${owned().length} / 9 territórios`;$('objectiveProgress').style.width=`${Math.min(100,owned().length/9*100)}%`;
    $('objectiveText').textContent=state.gameOver?(owned().length>=9?'Valdória está unida sob sua bandeira!':'A campanha chegou ao fim.'):'Conquiste 9 territórios para unir Valdória.';
    territories.forEach(t=>{const group=document.querySelector(`.territory-group[data-id="${t.id}"]`);if(!group)return;const path=group.querySelector('.territory');const f=faction(t.owner);path.style.fill=f.color;path.classList.toggle('selected',t.id===state.selected);const text=group.querySelector('.territory-army');text.textContent=`${t.troops}${t.fort?' ◆':''}`;group.setAttribute('aria-label',`${t.name}, ${f.name}, ${t.troops} divisões${t.fort?', fortificada':''}`)});
    renderSelection();renderLog();$('endTurnBtn').disabled=!state.started||state.gameOver;$('mapHint').classList.toggle('hidden',!!state.selected);$('phaseTitle').textContent=state.gameOver?(owned().length>=9?'Vitória!':'Campanha encerrada'):'Seu próximo movimento';$('phaseText').textContent=state.gameOver?(owned().length>=9?'Você conquistou o continente. Uma nova história começa quando quiser.':'Sua nação resistiu, mas não chegou à unificação.'):'Escolha uma região para recrutar, fortificar ou atacar um vizinho.';
    save();
  }
  function renderSelection(){const t=territory(state.selected);const card=$('selectionCard'),actions=$('actionButtons');actions.innerHTML='';$('selectionDetails').innerHTML='';if(!t){$('selectionFlag').innerHTML='◇';$('selectionName').textContent='Nenhum território';$('selectionSub').textContent='Toque no mapa para inspecionar';return}const f=faction(t.owner);$('selectionFlag').innerHTML=flagMarkup(flagConfigFor(t.owner));$('selectionName').textContent=t.name;$('selectionSub').textContent=`${f.name} · ${t.type.toLowerCase()}`;$('selectionDetails').innerHTML=`<span class="detail-chip">♟ <b>${t.troops}</b> divisões</span><span class="detail-chip">⌂ <b>${t.fort?`Nível ${t.fort}`:'Sem fortificação'}</b></span>${state.diplomacy[t.owner]&&t.owner!==state.player?'<span class="detail-chip">✦ Trégua ativa</span>':''}`;
    const make=(label,cost,cls,fn,disabled=false)=>{const b=document.createElement('button');b.className=`action-button ${cls}`;b.innerHTML=`${label}<small>${cost}</small>`;b.disabled=disabled;b.addEventListener('click',fn);actions.appendChild(b)};
    if(t.owner===state.player){make('＋ Recrutar','2 ind. · 1 rec.', 'action-green',()=>recruit(t),state.industry<2||state.manpower<1||state.gameOver);make('⌂ Fortificar','3 ind.', 'action-amber',()=>fortify(t),state.industry<3||t.fort>=2||state.gameOver);}
    else {const sources=adjacency[t.id].map(territory).filter(o=>o.owner===state.player);const source=sources.sort((a,b)=>b.troops-a.troops)[0];if(state.diplomacy[t.owner]){make('Trégua ativa','', 'action-muted',()=>toast('A trégua impede ataques neste turno.'),true)}else if(source){make(`⚔ Atacar de ${source.name}`,'1 divisão', 'action-red',()=>attack(source,t),state.attackDone||source.troops<2||state.gameOver);if(state.influence>=2)make('☮ Propor trégua','2 infl.', 'action-muted',()=>diplomacy(t),state.diplomacy[t.owner]||state.gameOver)}else{make('Sem fronteira','', 'action-muted',()=>{},true)}}
  }
  function selectTerritory(id){if(!state.started||state.gameOver)return;state.selected=id;const t=territory(id);$('mapCoord').textContent=`${(33+t.col*8).toString()}° N · ${(12+t.row*7).toString()}° L`;render()}
  function recruit(t){if(state.industry<2||state.manpower<1)return toast('Recursos insuficientes para recrutar.');state.industry-=2;state.manpower--;t.troops++;addLog(`Novas divisões chegaram a ${t.name}.`);toast(`Recrutas enviados para ${t.name}.`);render()}
  function fortify(t){if(state.industry<3||t.fort>=2)return toast('Não é possível fortificar esta região.');state.industry-=3;t.fort++;addLog(`${t.name} foi fortificada (nível ${t.fort}).`);toast(`${t.name} está mais protegida.`);render()}
  function attack(source,target){if(state.attackDone||source.troops<2)return;const attackers=source.troops-1;const defense=target.troops+target.fort;const roll=Math.random();const strength=attackers+(roll>.62?1:0);state.attackDone=true;source.troops=Math.max(1,source.troops-1);if(strength>defense){const old=faction(target.owner).name;target.owner=state.player;target.troops=Math.max(1,attackers-(strength>defense+1?0:1));target.fort=0;addLog(`${target.name} foi conquistada. ${old} recuou.`);toast(`${target.name} agora pertence a ${faction(state.player).name}.`);state.selected=target.id;if(owned().length>=9)finish(true)}else{target.troops=Math.max(1,target.troops-(attackers>defense?1:0));addLog(`Ataque a ${target.name} repelido. As tropas se reorganizam.`);toast('Ataque repelido. Recrute e tente novamente.')}render()}
  function diplomacy(t){if(state.influence<2)return toast('Influência insuficiente.');state.influence-=2;state.diplomacy[t.owner]=true;addLog(`Trégua temporária firmada com ${faction(t.owner).name}.`);toast(`Trégua com ${faction(t.owner).name} até o próximo turno.`);render()}
  function aiTurn(){for(const n of nations.filter(n=>n.id!==state.player)){let lands=territories.filter(t=>t.owner===n.id);if(!lands.length)continue;const borderline=lands.flatMap(a=>adjacency[a.id].map(territory).filter(b=>b.owner!==n.id&&!(state.diplomacy[b.owner]&&state.diplomacy[b.owner]===true)).map(b=>({from:a,to:b})));if(borderline.length){borderline.sort((a,b)=>(b.from.troops-a.from.troops)-(a.to.troops-b.to.troops));const option=borderline.find(x=>x.from.troops>=2&&x.to.troops+x.to.fort<=x.from.troops-1);if(option&&Math.random()<.54){const from=option.from,to=option.to,attackers=from.troops-1;from.troops--;if(attackers>to.troops+to.fort){to.owner=n.id;to.troops=Math.max(1,attackers-1);to.fort=0;addLog(`${n.name} ocupou ${to.name}.`)}else{to.troops=Math.max(1,to.troops-1);addLog(`${n.name} atacou ${to.name}, mas foi repelida.`)}}}
      lands=territories.filter(t=>t.owner===n.id);if(Math.random()<.42&&lands.length){lands.sort((a,b)=>a.troops-b.troops);lands[0].troops++;}
    }}
  function endTurn(){if(state.gameOver)return;state.turn++;state.attackDone=false;state.diplomacy={};const inc=income();state.industry+=inc.industry;state.manpower+=inc.manpower;state.influence+=inc.influence;aiTurn();if(owned().length>=9){finish(true)}else if(state.turn>12){finish(owned().length>=6)}else{addLog(`Turno ${state.turn}: recursos recebidos e exércitos mobilizados.`);$('mapStatus').textContent='TURNO '+state.turn+' · VALDÓRIA';render()}}
  function finish(win){state.gameOver=true;addLog(win?'Sua nação unificou Valdória!':'O armistício encerrou a campanha.');$('endTurnBtn').disabled=true;toast(win?'Vitória! Valdória está unida.':'Fim da campanha — tente uma nova estratégia.');render()}
  function addLog(message){state.log.unshift({turn:state.turn,message});state.log=state.log.slice(0,12)}
  function renderLog(){$('logList').innerHTML=state.log.length?state.log.slice(0,6).map(item=>`<div class="log-item"><span class="log-time">TURNO ${item.turn}</span><i class="log-dot"></i><span>${escapeHtml(item.message)}</span></div>`).join(''):'<div class="log-item"><span class="log-time">AGORA</span><span>O continente aguarda um novo líder.</span></div>'}
  function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
  function toast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
  function save(){try{localStorage.setItem('fronteiras-save',JSON.stringify({started:state.started,player:state.player,turn:state.turn,industry:state.industry,manpower:state.manpower,influence:state.influence,selected:state.selected,attackDone:state.attackDone,gameOver:state.gameOver,flag:state.flag,log:state.log,diplomacy:state.diplomacy,territories:territories.map(t=>({id:t.id,owner:t.owner,troops:t.troops,fort:t.fort}))}))}catch(_){}}
  function load(){try{const saved=JSON.parse(localStorage.getItem('fronteiras-save')||'null');if(!saved||!saved.started)return false;Object.assign(state,saved);saved.territories?.forEach(s=>{const t=territory(s.id);if(t)Object.assign(t,{owner:s.owner,troops:s.troops,fort:s.fort})});return true}catch(_){return false}}
  function startGame(id){state={started:true,player:id,turn:1,industry:5,manpower:5,influence:2,selected:null,attackDone:false,gameOver:false,flag:state.flag,log:[],diplomacy:{}};territories.forEach((t,i)=>{const initial=[3,2,2,3,2,3,2,2,2,2,3,2][i];t.troops=initial;t.fort=t.id==='caligo'?1:0});state.log.push({turn:1,message:`A nação de ${faction(id).name} inicia sua campanha.`});$('startModal').classList.remove('visible');$('mapStatus').textContent='MAPA DO CONTINENTE · TURNO 1';render();toast(`Campanha iniciada como ${faction(id).name}.`)}
  function openFlag(from){flagReturn=from;const playerId=state.player||selectedNation;const n=faction(playerId||'aurora');draftFlag={...(state.flag||n)};setFlagInputs();$('flagModal').classList.add('visible');}
  let selectedNation=null;
  function setFlagInputs(){$('flagPattern').value=draftFlag.pattern||'horizontal';$('flagSymbol').value=draftFlag.symbol||'★';drawSwatches('colorOne','c1');drawSwatches('colorTwo','c2');drawSwatches('colorThree','c3');drawPreview();document.querySelectorAll('.preset-btn').forEach((el,i)=>el.classList.toggle('active',draftFlag.c1===presets[i][1]&&draftFlag.pattern===presets[i][0]));}
  function drawSwatches(container,key){$(container).innerHTML=colorOptions.map(color=>`<button class="swatch ${draftFlag[key]===color?'active':''}" data-color="${color}" aria-label="Selecionar cor ${color}" style="background:${color}"></button>`).join('');$(container).querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{draftFlag[key]=b.dataset.color;setFlagInputs()}))}
  function drawPreview(){$('flagPreview').innerHTML=flagMarkup(draftFlag);}
  function setupNationGrid(){const el=$('nationGrid');el.innerHTML=nations.map(n=>`<button class="nation-choice" data-nation="${n.id}">${flagMarkup(n)}<span><strong>${n.name}</strong><small>${n.motto}</small></span><span class="difficulty">${n.difficulty}</span></button>`).join('');el.querySelectorAll('.nation-choice').forEach(b=>b.addEventListener('click',()=>{selectedNation=b.dataset.nation;el.querySelectorAll('.nation-choice').forEach(x=>x.classList.toggle('active',x===b));$('beginBtn').disabled=false;if(!state.flag){draftFlag={...faction(selectedNation)};drawPreview()}}))}
  function setupPresets(){$('presetList').innerHTML=presets.map((p,i)=>`<button class="preset-btn" aria-label="Combinação ${i+1}"><span class="flag" style="background:${p[0]==='vertical'?`linear-gradient(90deg,${p[1]} 0 33%,${p[2]} 33% 66%,${p[3]} 66%)`:p[0]==='diagonal'?`linear-gradient(135deg,${p[1]} 0 38%,${p[2]} 38% 67%,${p[3]} 67%)`:p[0]==='quartered'?`linear-gradient(90deg,${p[1]} 0 50%,${p[2]} 50%),linear-gradient(0deg,transparent 0 50%,${p[3]} 50%)`:p[0]==='cross'?`linear-gradient(90deg,transparent 0 40%,${p[3]} 40% 60%,transparent 60%),linear-gradient(0deg,${p[1]} 0 40%,${p[2]} 40% 60%,${p[1]} 60%)`:p[0]==='solid'?p[1]:`linear-gradient(0deg,${p[3]} 0 24%,${p[2]} 24% 76%,${p[1]} 76%)`}">${p[4]!=='—'?`<span class="flag-symbol" style="font-size:13px">${p[4]}</span>`:''}</span></button>`).join('');$('presetList').querySelectorAll('button').forEach((b,i)=>b.addEventListener('click',()=>{draftFlag={...draftFlag,pattern:presets[i][0],c1:presets[i][1],c2:presets[i][2],c3:presets[i][3],symbol:presets[i][4]};setFlagInputs()}))}
  function initialize(){initMap();setupNationGrid();setupPresets();$('flagPattern').addEventListener('change',e=>{draftFlag.pattern=e.target.value;drawPreview()});$('flagSymbol').addEventListener('change',e=>{draftFlag.symbol=e.target.value;drawPreview()});$('beginBtn').addEventListener('click',()=>{if(selectedNation)startGame(selectedNation)});$('startFlagBtn').addEventListener('click',()=>{if(!selectedNation)selectedNation='aurora';openFlag('startModal')});$('editFlagBtn').addEventListener('click',()=>openFlag(null));$('saveFlagBtn').addEventListener('click',()=>{state.flag={...draftFlag};$('flagModal').classList.remove('visible');if(flagReturn==='startModal'){$('startModal').classList.add('visible');}if(state.started)render();else if(selectedNation)paintFlag(document.querySelector('.nation-choice.active .flag'),state.flag);toast('Bandeira salva.')});document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>$(b.dataset.close).classList.remove('visible')));$('endTurnBtn').addEventListener('click',endTurn);$('newGameBtn').addEventListener('click',()=>{$('startModal').classList.add('visible');setupNationGrid();selectedNation=null;$('beginBtn').disabled=true;state.flag=null});$('settingsBtn').addEventListener('click',()=>openFlag(null));$('soundBtn').addEventListener('click',()=>toast('Esta campanha não usa sons — mais leve para seu celular.'));$('zoomIn').addEventListener('click',()=>{zoom=Math.min(1.3,zoom+.1);$('worldMap').style.transform=`scale(${zoom})`});$('zoomOut').addEventListener('click',()=>{zoom=Math.max(.85,zoom-.1);$('worldMap').style.transform=`scale(${zoom})`});$('startModal').addEventListener('click',e=>{if(e.target===$('startModal')&&state.started)$('startModal').classList.remove('visible')});$('flagModal').addEventListener('click',e=>{if(e.target===$('flagModal'))$('flagModal').classList.remove('visible')});if(load()){$('startModal').classList.remove('visible');render()}else setupNationGrid();}
  initialize();
})();

